import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.orders.api.OrderSummary;
import com.wolinski.shop.shipping.api.CarrierGateway;
import java.time.Instant;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class OrderService implements OrderFacade {

    private final OrderRepository orders;
    private final CarrierGateway carrier;
    private final TransactionTemplate transactions;

    public OrderService(OrderRepository orders, CarrierGateway carrier, PlatformTransactionManager transactions) {
        this.orders = orders;
        this.carrier = carrier;
        this.transactions = new TransactionTemplate(transactions);
    }

    @Override
    @Transactional
    public String place(String customerId, Money total, Instant placedAt) {
        Order order = new Order(UUID.randomUUID().toString(), customerId, total, placedAt);
        orders.save(order);
        return order.id();
    }

    /**
     * ADR 5: no carrier call inside a transaction. The status commits first, the shipment is booked after it,
     * and the tracking number is stored in a third step. If the carrier fails, the order stays CONFIRMED without
     * a tracking number and the error propagates; confirming again books the shipment. A confirmed order that
     * already has a tracking number is not booked twice.
     */
    @Override
    public void confirm(String orderId) {
        String existing = transactions.execute(status -> {
            Order order = orders.get(orderId);
            order.changeStatus("CONFIRMED");
            return order.trackingNumber();
        });
        if (existing != null) {
            return;
        }
        String trackingNumber = carrier.book(orderId);
        transactions.executeWithoutResult(status -> orders.get(orderId).assignTrackingNumber(trackingNumber));
    }

    @Override
    @Transactional
    public void cancel(String orderId) {
        orders.get(orderId).changeStatus("CANCELLED");
    }

    @Override
    @Transactional(readOnly = true)
    public OrderSummary summary(String orderId) {
        Order order = orders.get(orderId);
        return new OrderSummary(order.id(), order.customerId(), order.total(), order.status(), order.trackingNumber());
    }
}
}

