import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.InMemoryTransactionManager;
import com.wolinski.shop.shipping.api.CarrierGateway;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class OrderServiceConfirmTest {

    /** Records each booking and whether a transaction was open at that moment. */
    static class FakeCarrier implements CarrierGateway {
        final List<String> bookings = new ArrayList<>();
        final List<Boolean> transactionOpenDuringBooking = new ArrayList<>();
        boolean failNext;

        @Override
        public String book(String orderId) {
            transactionOpenDuringBooking.add(InMemoryTransactionManager.isOpen());
            if (failNext) {
                failNext = false;
                throw new IllegalStateException("carrier down");
            }
            bookings.add(orderId);
            return "TRK-" + orderId;
        }
    }

    private final FakeCarrier carrier = new FakeCarrier();
    private final OrderService orders = new OrderService(new OrderRepository(), carrier, new InMemoryTransactionManager());

    private String placeOrder() {
        return orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
    }

    @Test
    void confirmBooksAShipmentAndStoresTheTrackingNumber() {
        String id = placeOrder();
        assertNull(orders.summary(id).trackingNumber());

        orders.confirm(id);

        assertEquals("CONFIRMED", orders.summary(id).status());
        assertEquals("TRK-" + id, orders.summary(id).trackingNumber());
        assertEquals(List.of(id), carrier.bookings);
    }

    @Test
    void theCarrierIsCalledOutsideAnyTransaction() {
        orders.confirm(placeOrder());

        assertEquals(List.of(false), carrier.transactionOpenDuringBooking);
    }

    @Test
    void aCarrierFailureLeavesTheOrderConfirmedWithoutTrackingAndConfirmingAgainBooksIt() {
        String id = placeOrder();
        carrier.failNext = true;

        assertThrows(IllegalStateException.class, () -> orders.confirm(id));
        assertEquals("CONFIRMED", orders.summary(id).status());
        assertNull(orders.summary(id).trackingNumber());
        assertFalse(InMemoryTransactionManager.isOpen());

        orders.confirm(id);

        assertEquals("TRK-" + id, orders.summary(id).trackingNumber());
        assertEquals(List.of(id), carrier.bookings);
    }

    @Test
    void confirmingAnOrderTwiceBooksOnlyOnce() {
        String id = placeOrder();

        orders.confirm(id);
        orders.confirm(id);

        assertEquals(List.of(id), carrier.bookings);
        assertTrue(carrier.transactionOpenDuringBooking.stream().noneMatch(open -> open));
    }
}
}
